def rgb_to_hex(red: int, green: int, blue: int) -> str:
    """Converts RGB into hext string.

    Examples:
        >>> assert rgb_to_hex(1, 2, 3) == "010203"
    """

    def to_hex(number: int) -> str:
        if number > 255:
            return "FF"
        if number < 0:
            return "00"
        return f"{number:X}".zfill(2)

    return f"{to_hex(red)}{to_hex(green)}{to_hex(blue)}"

